LC_ALL=C; export LC_ALL
rapl() { if [ -e /sys/class/powercap/intel-rapl:0/energy_uj ]; then cat /sys/class/powercap/intel-rapl:0/energy_uj 2>/dev/null || sudo -n cat /sys/class/powercap/intel-rapl:0/energy_uj 2>/dev/null || echo denied; fi; }
units() { s=$1; shift; r=$(systemctl "$@" list-units --type=service --state=running --no-legend --plain 2>/dev/null) || return 0; echo "$s running $(printf '%s\n' "$r" | grep -c .)"; systemctl "$@" list-units --state=failed --no-legend --plain 2>/dev/null | awk -v s="$s" '{print s " failed " ($1 == "●" ? $2 : $1)}'; }
live_vols=$(mktemp -d 2>/dev/null) || live_vols=''
if [ -n "$live_vols" ]; then trap 'rm -rf "$live_vols"' EXIT; trap 'exit 1' HUP INT TERM PIPE; fi
live_mounts() { awk '$3 ~ /^(nfs4?|cifs|smb3|fuse\.(rclone|sshfs))$/ {print "share", $2; next} $1 ~ /^\/dev\// && $1 !~ /^\/dev\/loop/ {print $1, $2}' /proc/mounts 2>/dev/null | while read -r s m; do case $m in *\\*) m=$(printf '%b' "$m");; esac; if [ "$s" = share ] || [ ! -c "$s" ]; then printf '%s\n' "$m"; fi; done; }
live_ask() { if [ -z "$live_vols" ]; then live_mounts | while IFS= read -r m; do df -PkT "$m" 2>/dev/null | tail -n +2; done; return 0; fi; live_df=$(live_mounts | while IFS= read -r m; do k="$live_vols/$(printf '%s' "$m" | cksum | cut -d' ' -f1)"; echo "$k.out"; if [ -e "$k.ask" ]; then rm -f "$k.out"; else : > "$k.ask"; { df -PkT "$m" 2>/dev/null | tail -n +2 > "$k.new"; mv -f "$k.new" "$k.out"; rm -f "$k.ask"; } </dev/null >/dev/null 2>&1 & fi; done); }
live_volumes() { [ -n "$live_vols" ] || return 0; echo @@df; [ -n "$live_df" ] && cat $live_df 2>/dev/null; return 0; }
n=$(command -v nvidia-smi 2>/dev/null); [ -z "$n" ] && [ -x /usr/lib/wsl/lib/nvidia-smi ] && n=/usr/lib/wsl/lib/nvidia-smi
live_seldom() { echo @@host; cat /proc/sys/kernel/hostname 2>/dev/null; echo @@kernel; uname -r 2>/dev/null; echo @@version; cat /proc/version 2>/dev/null; echo @@os; grep -E '^(PRETTY_NAME|NAME|VERSION_ID)=' /etc/os-release 2>/dev/null; echo @@model; grep -m1 '^model name' /proc/cpuinfo 2>/dev/null; echo @@layout; grep -Hs . /sys/devices/system/cpu/cpu[0-9]*/topology/physical_package_id /sys/devices/system/cpu/cpu[0-9]*/topology/core_id /sys/devices/system/cpu/cpu[0-9]*/cache/index3/shared_cpu_list /sys/devices/system/cpu/cpu[0-9]*/cache/index3/size; echo @@blk; lsblk -bnPo NAME,PKNAME,TYPE,SIZE,MODEL,ROTA,TRAN 2>/dev/null; echo @@blkdev; for b in /sys/block/*; do d=$(readlink "$b/device" 2>/dev/null); [ -n "$d" ] && echo "${b##*/} ${d##*/}"; done; echo @@df; live_ask; echo @@services; if command -v systemctl >/dev/null 2>&1; then units system; units user --user; fi; }
live_often() { echo @@uptime; read live_up live_idle </proc/uptime; echo "$live_up"; echo @@loadavg; cat /proc/loadavg 2>/dev/null; echo @@meminfo; grep -E '^(MemTotal|MemAvailable|SwapTotal|SwapFree):' /proc/meminfo 2>/dev/null; echo @@stat; grep '^cpu' /proc/stat 2>/dev/null; echo @@rapl; rapl; echo @@clock; grep -Hs . /sys/devices/system/cpu/cpu[0-9]*/cpufreq/scaling_cur_freq; [ -e /sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq ] || { echo @@cpumhz; grep -E '^(processor|cpu MHz)' /proc/cpuinfo 2>/dev/null; }; echo @@hwmon; for h in /sys/class/hwmon/hwmon*; do [ -d "$h" ] || continue; d=$(readlink "$h/device" 2>/dev/null); echo "chip $h $(cat "$h/name" 2>/dev/null) ${d##*/}"; grep -Hs . "$h"/temp*_input "$h"/temp*_label "$h"/temp*_crit "$h"/temp*_max "$h"/fan*_input "$h"/fan*_label; done; echo @@gpu; [ -n "$n" ] && "$n" --query-gpu=index,name,utilization.gpu,temperature.gpu,clocks.gr,clocks.max.gr,clocks.mem,power.draw,power.limit,memory.used,memory.total,fan.speed,clocks_throttle_reasons.hw_thermal_slowdown,clocks_throttle_reasons.sw_thermal_slowdown --format=csv,noheader,nounits 2>/dev/null; }
live_reading() { if [ $1 -eq 0 ]; then echo @@gpureport; [ -n "$n" ] && "$n" -q -x 2>/dev/null; fi; if [ $(($1 % 30)) -eq 0 ]; then live_seldom; fi; live_often; live_volumes; }
live_now() { read live_t live_idle </proc/uptime; live_cs=${live_t%.*}${live_t#*.}; }
live_k=0
if grep -qi microsoft /proc/version 2>/dev/null && [ -x /mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe ]; then
  live_cr=$(printf '\r'); live_win=''
  /mnt/c/Windows/System32/WindowsPowerShell/v1.0/powershell.exe -NoProfile -NonInteractive -EncodedCommand  </dev/null 2>/dev/null | while IFS= read -r live_line; do
    live_line=${live_line%"$live_cr"}
    if [ "$live_line" = @@winend ]; then live_reading $live_k; echo @@win; printf '%s' "$live_win"; echo @@end; live_k=$((live_k + 1)); live_win=''
    else live_win="$live_win$live_line
"; fi
  done
else
  live_now; live_end=$((live_cs + 24000)); live_next=$live_cs
  while [ $live_cs -lt $live_end ]; do
    live_reading $live_k; echo @@end; live_k=$((live_k + 1))
    live_next=$((live_next + 100)); live_now; live_wait=$((live_next - live_cs))
    if [ $live_wait -gt 0 ]; then sleep "$((live_wait / 100)).$((live_wait % 100 / 10))$((live_wait % 10))"; else live_next=$live_cs; fi
  done
fi